      .standard-cinema-details{
        grid-template-columns:1fr;
      }
      .standard-cinema-item{
        grid-template-columns:40px 1fr;
        min-height:0;
        padding:24px 24px;
        border-right:0;
        border-bottom:1px solid rgba(255,255,255,.10);
      }
      .standard-cinema-item:last-child{border-bottom:0}
      .standard-cinema-item h3{
        font-size:15px;
        margin-bottom:9px;
      }
      .standard-cinema-item p{
        font-size:11.5px;
        line-height:1.62;
        color:rgba(255,255,255,.66);
      }
    }

    @media(max-width:390px){
      .standard-cinema-visual{min-height:560px}
      .standard-cinema-top{left:18px;right:18px}
      .standard-cinema-copy{left:18px;right:18px}
      .standard-cinema-brands{left:18px;right:18px;font-size:7px}
      .standard-cinema-copy h2{font-size:43px}
      .standard-cinema-item{padding-left:18px;padding-right:18px}
    }


    /* v29 — vídeo cinematográfico na seção Padrão MK3 */
    .standard-cinema-visual{
      min-height:690px;
      background:
        radial-gradient(circle at 77% 42%,rgba(255,255,255,.035),transparent 24%),
        linear-gradient(105deg,#040609 0%,#05070a 45%,#080b10 100%);
    }

    .standard-cinema-video-wrap{
      position:absolute;
      top:0;
      right:0;
      bottom:0;
      width:48%;
      overflow:hidden;
      background:#090b0e;
      box-shadow:-28px 0 90px rgba(0,0,0,.48);
    }

    .standard-cinema-video-wrap::before{
      content:"";
      position:absolute;
      inset:0;
      z-index:2;
      pointer-events:none;
      background:
        linear-gradient(90deg,
          #05070a 0%,
          rgba(5,7,10,.90) 8%,
          rgba(5,7,10,.54) 20%,
          rgba(5,7,10,.12) 42%,
          rgba(5,7,10,.03) 100%),
        linear-gradient(0deg,
          rgba(4,6,9,.50) 0%,
          transparent 28%,
          transparent 72%,
          rgba(4,6,9,.15) 100%);
    }

    .standard-cinema-video-wrap::after{
      content:"";
      position:absolute;
      inset:0;
      z-index:3;
      pointer-events:none;
      border-left:1px solid rgba(255,255,255,.07);
      background:
        radial-gradient(circle at 62% 48%,transparent 35%,rgba(3,5,8,.16) 100%);
    }

    .standard-cinema-video{
      position:absolute;
      inset:0;
      width:100%;
      height:100%;
      object-fit:cover;
      object-position:center 48%;
      filter:saturate(.93) contrast(1.05) brightness(.88);
      transform:scale(1.035);
    }

    .standard-cinema-shade{
      z-index:1;
      background:
        linear-gradient(90deg,
          rgba(3,5,8,.98) 0%,
          rgba(3,5,8,.94) 34%,
          rgba(3,5,8,.73) 51%,
          rgba(3,5,8,.18) 70%,
          transparent 88%),
        linear-gradient(0deg,
          rgba(3,5,8,.91) 0%,
          rgba(3,5,8,.20) 42%,
          rgba(3,5,8,.06) 100%);
      pointer-events:none;
    }

    .standard-cinema-copy{
      z-index:4;
      width:min(650px,54%);
      bottom:116px;
    }

    .standard-cinema-copy h2{
      text-shadow:0 12px 38px rgba(0,0,0,.52);
    }

    .standard-cinema-copy p{
      color:rgba(255,255,255,.78);
      text-shadow:0 4px 18px rgba(0,0,0,.58);
    }

    .standard-cinema-top,
    .standard-cinema-brands{
      z-index:4;
    }

    .standard-cinema-brands{
      right:4.5%;
      bottom:34px;
      padding:10px 14px;
      border:1px solid rgba(255,255,255,.08);
      border-radius:999px;
      background:rgba(5,7,10,.28);
      backdrop-filter:blur(12px);
      -webkit-backdrop-filter:blur(12px);
    }

    @media(max-width:999px){
      .standard-cinema-visual{
        min-height:650px;
      }
      .standard-cinema-video-wrap{
        width:56%;
      }
      .standard-cinema-copy{
        width:min(600px,62%);
      }
    }

    @media(max-width:720px){
      .standard-cinema-visual{
        min-height:650px;
      }

      .standard-cinema-video-wrap{
        inset:0;
        width:100%;
        height:100%;
        box-shadow:none;
      }

      .standard-cinema-video-wrap::before{
        background:
          linear-gradient(0deg,
            rgba(3,5,8,.98) 0%,
            rgba(3,5,8,.92) 31%,
            rgba(3,5,8,.65) 49%,
            rgba(3,5,8,.20) 70%,
            rgba(3,5,8,.05) 100%),
          linear-gradient(90deg,
            rgba(3,5,8,.30) 0%,
            transparent 55%,
            rgba(3,5,8,.06) 100%);
      }

      .standard-cinema-video-wrap::after{
        border-left:0;
        border-top:1px solid rgba(255,255,255,.06);
        background:
          radial-gradient(circle at 50% 30%,transparent 28%,rgba(3,5,8,.20) 100%);
      }

      .standard-cinema-video{
        object-fit:cover;
        object-position:center 40%;
        filter:saturate(.96) contrast(1.04) brightness(.86);
        transform:scale(1.02);
      }

      .standard-cinema-shade{
        background:
          linear-gradient(0deg,
            rgba(3,5,8,.99) 0%,
            rgba(3,5,8,.91) 34%,
            rgba(3,5,8,.59) 53%,
            rgba(3,5,8,.16) 72%,
            rgba(3,5,8,.03) 100%);
      }

      .standard-cinema-copy{
        left:24px;
        right:24px;
        bottom:96px;
        width:auto;
      }

      .standard-cinema-copy h2{
        font-size:clamp(45px,12.5vw,64px);
      }

      .standard-cinema-copy p{
        max-width:94%;
        font-size:13px;
        line-height:1.6;
      }

      .standard-cinema-brands{
        left:24px;
        right:auto;
        bottom:24px;
        max-width:calc(100% - 48px);
        padding:9px 11px;
        gap:10px;
        background:rgba(5,7,10,.42);
        overflow:hidden;
      }
    }

    @media(max-width:390px){
      .standard-cinema-visual{
        min-height:625px;
      }
      .standard-cinema-copy{
        left:18px;
        right:18px;
        bottom:90px;
      }
      .standard-cinema-brands{
        left:18px;
        max-width:calc(100% - 36px);
      }
      .standard-cinema-copy h2{
        font-size:42px;
      }
    }

    @media(prefers-reduced-motion:reduce){
      .standard-cinema-video{
        display:none;
      }
      .standard-cinema-video-wrap{
        background:
          linear-gradient(0deg,rgba(3,5,8,.65),rgba(3,5,8,.10)),
          url("data:image/jpeg;base64,") center 42% / cover no-repeat;
      }
    }

